/**
 * Any object a `Proxy` can wrap.
 *
 * @deprecated Nothing in @tolki reads it; the next major removes it.
 */
export type ProxyTarget = object;

/**
 * A property key a `Proxy` trap receives.
 *
 * @deprecated Nothing in @tolki reads it; the next major removes it.
 */
export type PropertyName = string | symbol;
